\begin{theorem}[Hamilton, 3-manifolds with positive Ricci curvature]
\label{thm:chow-ii-appd-hamilton-positive-ricci-three-manifolds}
\source{chow-et-al-ricci-flow-part-ii:page-0385}
\dcref{appD:D.7}
\group{Ricci Flow Convergence}

If $(\mathcal M^3,g_0)$ is closed and has positive Ricci curvature, its
normalized Ricci flow exists for all $t\geq0$ and converges exponentially in
every $C^m$ norm to a smooth metric of constant positive sectional curvature.
\end{theorem}

